import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"JNTemplate","description":"","frontmatter":{},"headers":[],"relativePath":"started/about.md","filePath":"started/about.md","lastUpdated":0}`),a={name:`started/about.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="jntemplate" tabindex="-1">JNTemplate <a class="header-anchor" href="#jntemplate" aria-label="Permalink to “JNTemplate”">​</a></h1><hr><p><strong>About JNTemplate</strong></p><p>The Chinese name of JNTemplate is &quot;极念模板引擎&quot; (Ji Nian Template Engine). &quot;JN&quot; comes from the pinyin initials of 极念: 极 (jí) means extreme or ultimate — the best; 念 (niàn) means idea or concept. So the name can be understood as &quot;the best idea, the greatest concept&quot;.</p><p>JNTemplate is a text parsing engine written entirely in C#. It can generate any text-based content: you can use it to render web templates, or as a code generator, an XML document generator, or for any other purpose you can think of.</p><p><strong>Why choose JNTemplate</strong></p><ol><li>Stable: we have kept iterating since the .NET Framework 2.0 era, continuously improving features and providing technical support, and its stability has been validated by the community.</li><li>Fast: code is compiled with IL emit, and it performs well in both compilation and execution speed.</li><li>Free: fully usable for commercial purposes, with no fees at all.</li><li>Simple: concise and easy to use, with a low learning curve.</li></ol><p><strong>Why JNTemplate when Razor exists?</strong></p><p>As Microsoft&#39;s official view engine, Razor is undoubtedly the best choice in ASP.NET MVC. In some scenarios, however, we may need a more flexible and lightweight template engine, so the two do not conflict.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};